NP_functionality.VERILOG_PROVIDED:
generate
  if(PIPE_PARAMETER==1)
  begin
    reg [BITSIZE_out1-1:0] out1_reg;
    assign out1 = out1_reg;
    always @(posedge clock)
    begin
      out1_reg <= lhs * rhs;
    end
  end
  else if(PIPE_PARAMETER>1)
  begin
    reg [BITSIZE_lhs-1:0] lhs_in;
    reg [BITSIZE_rhs-1:0] rhs_in;
    wire [BITSIZE_out1-1:0] mult_res;
    reg [BITSIZE_out1-1:0] mul [PIPE_PARAMETER-2:0];
    integer i;
    assign mult_res = lhs_in * rhs_in;
    always @(posedge clock)
    begin
      lhs_in <= lhs;
      rhs_in <= rhs;
      mul[PIPE_PARAMETER-2] <= mult_res;
      for (i=0; i<PIPE_PARAMETER-2; i=i+1)
        mul[i] <= mul[i+1];
    end
    assign out1 = mul[0];
  end
  else
  begin
    assign out1 = lhs * rhs;
  end
endgenerate

NP_functionality.VHDL_PROVIDED:
  signal lhs_int : unsigned (BITSIZE_lhs-1 downto 0);
  signal rhs_int : unsigned (BITSIZE_rhs-1 downto 0);
begin
  cond: if(PIPE_PARAMETER=0) generate
    out1 <= resize(lhs * rhs, BITSIZE_out1);
  end generate cond;
  cond1 : if(PIPE_PARAMETER=1) generate
    out1 <= resize(lhs_int * rhs_int, BITSIZE_out1);
    process(clock)
    begin
      if clock'event and clock = '1' then
        lhs_int <= lhs;
        rhs_int <= rhs;
      end if;
    end process;
  end generate cond1;
  cond2 : if(PIPE_PARAMETER >1) generate
    type levels_of_registers is array (PIPE_PARAMETER-1 downto 0) of unsigned (BITSIZE_out1-1 downto 0);
    signal out1_int : levels_of_registers;
  begin
    out1 <= out1_int (0);
    process(clock)
    begin
      if clock'event and clock = '1' then
        lhs_int <= lhs;
        rhs_int <= rhs;
        out1_int(PIPE_PARAMETER-2) <= resize(lhs_int * rhs_int, BITSIZE_out1);
        for i in 0 to PIPE_PARAMETER-3 loop
          out1_int (i) <= out1_int (i+1);
        end loop;
      end if;
    end process;
  end generate cond2;
